from __future__ import annotations

import math
from bisect import bisect_left
from datetime import datetime, timedelta

REQUIRED_LOOKBACK_SECONDS = 8380800


def _window(times, values, end, seconds):
    """取 [end - seconds, end) 内的值。**end 一律不含**，这是 PIT 的关键。"""
    lo = bisect_left(times, end - timedelta(seconds=seconds))
    hi = bisect_left(times, end)
    return values[lo:hi]


def _agg(op, xs):
    if not xs:
        return None
    if op == "last":
        return xs[-1]
    if op == "mean":
        return math.fsum(xs) / len(xs)
    if op == "sum":
        return math.fsum(xs)
    if op == "count":
        return float(len(xs))
    if op == "min":
        return min(xs)
    if op == "max":
        return max(xs)
    if op == "std":
        if len(xs) < 2:
            return None
        m = math.fsum(xs) / len(xs)
        return math.sqrt(math.fsum((x - m) ** 2 for x in xs) / (len(xs) - 1))
    raise ValueError(op)


def _ok(v):
    """非有限值一律当作无定义：NaN 传下去会让比较式的闸门全部取假地通过。"""
    return v is not None and math.isfinite(v)


def _at_iran_p_studentised_range_7d(at: datetime, series: dict):
    """在任意过去时刻求 iran_p_studentised_range_7d 的值。参考分布要用它。"""
    t, x = series["pm_market.cand:iran:p"]
    end = at - timedelta(seconds=0)
    v_iran_p_max_7d = _agg("max", _window(t, x, end, 604800))
    t, x = series["pm_market.cand:iran:p"]
    end = at - timedelta(seconds=0)
    v_iran_p_min_7d = _agg("min", _window(t, x, end, 604800))
    v_iran_p_range_7d = (v_iran_p_max_7d - v_iran_p_min_7d) if _ok(v_iran_p_max_7d) and _ok(v_iran_p_min_7d) else None
    t, x = series["pm_market.cand:iran:p"]
    end = at - timedelta(seconds=0)
    v_iran_p_std_7d = _agg("std", _window(t, x, end, 604800))
    v_iran_p_studentised_range_7d = (v_iran_p_range_7d / v_iran_p_std_7d) if _ok(v_iran_p_range_7d) and _ok(v_iran_p_std_7d) and v_iran_p_std_7d != 0 else None
    return v_iran_p_studentised_range_7d

def compute(decision_time: datetime, series: dict, coverage_start=None):
    """在一个决策时点上求值。无定义返回 None。"""
    # 覆盖准入：回看深度必须整段落在序列覆盖范围内，否则同一份规格在完整
    # 序列与其截断副本上会给出不同的数，而没有任何记录能看出差别
    if coverage_start is not None and (
        decision_time - timedelta(seconds=REQUIRED_LOOKBACK_SECONDS)
        < coverage_start
    ):
        return None
    t_iran_p_max_7d, x_iran_p_max_7d = series["pm_market.cand:iran:p"]
    end_iran_p_max_7d = decision_time - timedelta(seconds=0)
    v_iran_p_max_7d = _agg("max", _window(t_iran_p_max_7d, x_iran_p_max_7d, end_iran_p_max_7d, 604800))
    v_iran_p_max_7d = v_iran_p_max_7d if _ok(v_iran_p_max_7d) else None
    if v_iran_p_max_7d is not None and not math.isfinite(v_iran_p_max_7d):
        v_iran_p_max_7d = None
    t_iran_p_min_7d, x_iran_p_min_7d = series["pm_market.cand:iran:p"]
    end_iran_p_min_7d = decision_time - timedelta(seconds=0)
    v_iran_p_min_7d = _agg("min", _window(t_iran_p_min_7d, x_iran_p_min_7d, end_iran_p_min_7d, 604800))
    v_iran_p_min_7d = v_iran_p_min_7d if _ok(v_iran_p_min_7d) else None
    if v_iran_p_min_7d is not None and not math.isfinite(v_iran_p_min_7d):
        v_iran_p_min_7d = None
    v_iran_p_range_7d = (v_iran_p_max_7d - v_iran_p_min_7d) if _ok(v_iran_p_max_7d) and _ok(v_iran_p_min_7d) else None
    if v_iran_p_range_7d is not None and not math.isfinite(v_iran_p_range_7d):
        v_iran_p_range_7d = None
    t_iran_p_std_7d, x_iran_p_std_7d = series["pm_market.cand:iran:p"]
    end_iran_p_std_7d = decision_time - timedelta(seconds=0)
    v_iran_p_std_7d = _agg("std", _window(t_iran_p_std_7d, x_iran_p_std_7d, end_iran_p_std_7d, 604800))
    v_iran_p_std_7d = v_iran_p_std_7d if _ok(v_iran_p_std_7d) else None
    if v_iran_p_std_7d is not None and not math.isfinite(v_iran_p_std_7d):
        v_iran_p_std_7d = None
    v_iran_p_studentised_range_7d = (v_iran_p_range_7d / v_iran_p_std_7d) if _ok(v_iran_p_range_7d) and _ok(v_iran_p_std_7d) and v_iran_p_std_7d != 0 else None
    if v_iran_p_studentised_range_7d is not None and not math.isfinite(v_iran_p_studentised_range_7d):
        v_iran_p_studentised_range_7d = None
    # residualise：拟合样本严格取自决策时点之前，逐点重拟合
    tc_iran_p_jump_shape_resid, xc_iran_p_jump_shape_resid = series["commodity_bar.realised_volatility"]
    xs_iran_p_jump_shape_resid, cs_iran_p_jump_shape_resid = [], []
    for k in range(1, 90 + 1):
        past = decision_time - timedelta(seconds=k * 86400)
        xv = _at_iran_p_studentised_range_7d(past, series)
        cw = _window(tc_iran_p_jump_shape_resid, xc_iran_p_jump_shape_resid, past, 7776000)
        cv = cw[-1] if cw else None
        if _ok(xv) and _ok(cv):
            xs_iran_p_jump_shape_resid.append(xv)
            cs_iran_p_jump_shape_resid.append(cv)
    cw0 = _window(tc_iran_p_jump_shape_resid, xc_iran_p_jump_shape_resid, decision_time, 7776000)
    c0 = cw0[-1] if cw0 else None
    if not _ok(v_iran_p_studentised_range_7d) or not _ok(c0) or len(set(cs_iran_p_jump_shape_resid)) < 40:
        v_iran_p_jump_shape_resid = None
    else:
        cbar = math.fsum(cs_iran_p_jump_shape_resid) / len(cs_iran_p_jump_shape_resid)
        xbar = math.fsum(xs_iran_p_jump_shape_resid) / len(xs_iran_p_jump_shape_resid)
        scc = math.fsum((c - cbar) ** 2 for c in cs_iran_p_jump_shape_resid)
        if scc <= 0:
            v_iran_p_jump_shape_resid = None
        else:
            b = math.fsum((c - cbar) * (x - xbar) for c, x in zip(cs_iran_p_jump_shape_resid, xs_iran_p_jump_shape_resid, strict=True)) / scc
